请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-014

=== 用户原始指令 (query.txt) ===
手机又满了！做个简洁的卡片，上方左右并排展示“剩余空间15%”和当前电量，弄点适合深夜倒计时的渐变色，表现出那种危险超限的告警感。下面横向重复排列几个占用内存的App图标，点一下卡片就能帮我直接开启系统的超级省电模式开关。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "手机又满了！做个简洁的卡片，上方左右并排展示“剩余空间15%”和当前电量，弄点适合深夜倒计时的渐变色，表现出那种危险超限的告警感。下面横向重复排列几个占用内存的App图标，点一下卡片就能帮我直接开启系统的超级省电模式开关。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModelSchema": {
    "storage": {
      "remainingText": {
        "type": "string",
        "description": "剩余存储空间百分比展示文本。",
        "sampleValue": "剩余空间15%"
      }
    },
    "battery": {
      "currentText": {
        "type": "string",
        "description": "当前电量百分比展示文本。",
        "sampleValue": "电量22%"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_tiktok.png",
      "description": "短视频 App 图标素材，适合表示占用内存较高的娱乐应用。"
    },
    {
      "src": "resources/base/media/icon_music.png",
      "description": "音乐 App 图标素材，适合表示缓存音频占用。"
    },
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标素材，适合表示系统缓存或待清理项。"
    },
    {
      "src": "resources/base/media/icon_phone.png",
      "description": "手机图标素材，适合表示系统与本机存储占用。"
    }
  ]
}

